// ---------------------------------------------------------------- type-level machinery

/**
 * What a JSON import of a value of type T is assignable to: literal unions widen to their
 * primitive and tuples to arrays (a JSON import infers `string`, `number[][]`), structure stays.
 */
type Loose<T> = T extends string
  ? string
  : T extends number
    ? number
    : T extends boolean
      ? boolean
      : T extends null
        ? null
        : T extends readonly (infer E)[]
          ? Loose<E>[]
          : T extends object
            ? { [K in keyof T]: Loose<T[K]> }
            : T;

type AllKeys<T> = T extends unknown ? keyof T : never;
type At<T, K extends PropertyKey> = T extends unknown ? (K extends keyof T ? T[K] : never) : never;
type Elem<T> = T extends readonly (infer E)[] ? E : never;

/** Dotted paths of keys the fixture V has and the TS type T does not declare (deeply). */
type ExtraKeys<T, V, P extends string = ''> = unknown extends T
  ? never
  : V extends readonly (infer E)[]
    ? ExtraKeys<Elem<NonNullable<T>>, E, `${P}[]`>
    : V extends object
      ? {
          [K in keyof V & string]: K extends AllKeys<NonNullable<T>>
            ? ExtraKeys<At<NonNullable<T>, K>, V[K], `${P}.${K}`>
            : `${P}.${K}`;
        }[keyof V & string]
      : never;

type Exactly<T, M> = {
  [K in keyof M]: [ExtraKeys<T, M[K]>] extends [never]
    ? unknown
    : { 'keys the TS type lacks': ExtraKeys<T, M[K]> };
};

/**
 * A family of fixtures of one TS type T, by file name. The argument must already `satisfies`
 * `Record<string, Loose<T>>`; this adds the no-extra-keys check.
 */
function exactly<T>() {
  return <M extends Record<string, Loose<T>>>(
    fixtures: M & Exactly<T, M>,
  ): Record<string, unknown> => fixtures;
}

/** Every member of the union T, so a new literal on the TS side must be listed. */
function allOf<T extends string>() {
  return <A extends readonly T[]>(
    values: A &
      ([Exclude<T, A[number]>] extends [never] ? unknown : { missing: Exclude<T, A[number]> }),
  ): readonly string[] => values;
}

/** The keys of T, complete and with nothing extra (checked as a fresh object literal). */
function keysOf<T>() {
  return (manifest: Record<keyof T, true>): string[] => Object.keys(manifest).sort();
}

