/** A report of workload K whose results are exactly R (one mode's example). */
type ModeReport<K extends WorkloadKind, R> = Omit<RunReportOf<K>, 'results'> & { results: R };
const modeOf = <K extends WorkloadKind, R>() => exactly<ModeReport<K, R>>();

